sp_widget.client_script:
api.controller=function($scope, $window) {

    var c = this;


    // -----------------------------------------
    // CREATE ASSESSMENT
    // -----------------------------------------

    c.createAssessment = function() {

        $window.location.href =
            '?id=campus360_create_assessment';

    };


    // -----------------------------------------
    // VIEW ASSESSMENT
    // -----------------------------------------

    c.viewAssessment = function(assessment) {

        if (!assessment || !assessment.sys_id) {
            return;
        }

        $window.location.href =
            '?id=campus360_assessment_view&sys_id=' +
            assessment.sys_id;
    };

}

sp_widget.css:
/* =========================================
   CAMPUS360 ASSESSMENTS PAGE
   ========================================= */

.c360-assessments-page {
  width: 100%;
  min-height: 100vh;
  background: #f5f7fb;
  padding: 30px 24px 60px;
  box-sizing: border-box;
}

.c360-assessments-container {
  max-width: 1150px;
  margin: 0 auto;
}


/* =========================================
   PAGE HEADER
   ========================================= */

.c360-page-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 22px;
}

.c360-eyebrow {
  color: #5b52e8;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  margin-bottom: 6px;
}

.c360-page-header h1 {
  margin: 0;
  color: #10194f;
  font-size: 24px;
  font-weight: 600;
}

.c360-page-header p {
  margin: 7px 0 0;
  color: #7b7f9c;
  font-size: 12px;
}


/* =========================================
   CREATE BUTTON
   ========================================= */

.c360-create-btn {
  display: flex;
  align-items: center;
  gap: 7px;

  height: 38px;
  padding: 0 16px;

  border: none;
  border-radius: 6px;

  background: #5b52e8;
  color: #ffffff;

  font-size: 11px;
  font-weight: 600;

  cursor: pointer;

  transition: background 0.2s ease,
              transform 0.1s ease;
}

.c360-create-btn span {
  font-size: 17px;
  font-weight: 400;
}

.c360-create-btn:hover {
  background: #493fd2;
}

.c360-create-btn:active {
  transform: translateY(1px);
}


/* =========================================
   MAIN PANEL
   ========================================= */

.c360-panel {
  background: #ffffff;
  border: 1px solid #dedff0;
  border-radius: 12px;
  padding: 20px;
  box-shadow: 0 3px 12px rgba(50, 55, 110, 0.03);
}


/* =========================================
   PANEL HEADER
   ========================================= */

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;

  padding-bottom: 16px;
  border-bottom: 1px solid #eeeeF5;
}

.panel-eyebrow {
  color: #5b52e8;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1px;
  margin-bottom: 5px;
}

.panel-header h2 {
  margin: 0;
  color: #111a4d;
  font-size: 17px;
  font-weight: 600;
}

.assessment-count {
  color: #777b9a;
  font-size: 11px;
}


/* =========================================
   ASSESSMENT TABLE
   ========================================= */

.assessment-table {
  width: 100%;
  margin-top: 5px;
}


/* =========================================
   TABLE HEADER
   ========================================= */

.assessment-table-header {
  display: grid;

  grid-template-columns:
    1.5fr
    1.35fr
    1fr
    1fr
    0.8fr
    0.9fr
    0.65fr;

  align-items: center;

  min-height: 42px;

  padding: 0 10px;

  color: #777b9a;

  font-size: 9px;
  font-weight: 700;

  letter-spacing: 0.5px;

  border-bottom: 1px solid #e6e7f2;
}


/* =========================================
   TABLE ROW
   ========================================= */

.assessment-row {
  display: grid;

  grid-template-columns:
    1.5fr
    1.35fr
    1fr
    1fr
    0.8fr
    0.9fr
    0.65fr;

  align-items: center;

  min-height: 62px;

  padding: 0 10px;

  border-bottom: 1px solid #eeeeF5;

  color: #20275a;

  font-size: 11px;
}

.assessment-row:last-child {
  border-bottom: none;
}


/* =========================================
   ASSESSMENT NAME
   ========================================= */

.assessment-name-cell {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.assessment-name-cell strong {
  color: #111a4d;
  font-size: 12px;
  font-weight: 600;
}

.assessment-name-cell small {
  color: #9296b1;
  font-size: 9px;
}


/* =========================================
   OTHER CELLS
   ========================================= */

.assessment-opportunity {
  color: #4f5680;
  font-size: 11px;
}

.assessment-type {
  color: #4f5680;
  font-size: 11px;
}

.assessment-date {
  color: #5d6385;
  font-size: 10px;
}

.assessment-score {
  color: #111a4d;
  font-size: 11px;
  font-weight: 600;
}


/* =========================================
   STATUS
   ========================================= */

.assessment-status {
  display: inline-flex;

  align-items: center;
  justify-content: center;

  padding: 5px 9px;

  border-radius: 6px;

  font-size: 9px;
  font-weight: 600;

  white-space: nowrap;
}


/* PUBLISHED */

.status-published {
  background: #dcf8ed;
  color: #16845c;
}


/* DRAFT */

.status-draft {
  background: #eee9ff;
  color: #635bdb;
}


/* CLOSED */

.status-closed {
  background: #ffe5e5;
  color: #d84b4b;
}


/* =========================================
   VIEW BUTTON
   ========================================= */

.assessment-view {
  border: none;
  background: transparent;

  color: #5b52e8;

  font-size: 10px;
  font-weight: 500;

  padding: 4px 0;

  cursor: pointer;
}

.assessment-view:hover {
  color: #3f36c9;
  text-decoration: underline;
}


/* =========================================
   EMPTY STATE
   ========================================= */

.assessment-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  min-height: 280px;

  text-align: center;
}

.empty-icon {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 52px;
  height: 52px;

  margin-bottom: 14px;

  border-radius: 14px;

  background: #f0efff;

  color: #5b52e8;

  font-size: 24px;
}

.assessment-empty strong {
  color: #111a4d;
  font-size: 13px;
  font-weight: 600;
}

.assessment-empty p {
  margin: 7px 0 15px;

  color: #9296b1;

  font-size: 11px;
}


/* =========================================
   EMPTY CREATE BUTTON
   ========================================= */

.empty-create-btn {
  height: 34px;

  padding: 0 15px;

  border: 1px solid #d9d7ff;
  border-radius: 6px;

  background: #f8f7ff;

  color: #5b52e8;

  font-size: 10px;
  font-weight: 600;

  cursor: pointer;
}

.empty-create-btn:hover {
  background: #efedff;
}


/* =========================================
   RESPONSIVE
   ========================================= */

@media (max-width: 900px) {

  .assessment-table {
    overflow-x: auto;
  }

  .assessment-table-header,
  .assessment-row {
    min-width: 900px;
  }

}

@media (max-width: 600px) {

  .c360-assessments-page {
    padding: 20px 12px 40px;
  }

  .c360-page-header {
    flex-direction: column;
    gap: 14px;
  }

  .c360-create-btn {
    width: 100%;
    justify-content: center;
  }

  .c360-panel {
    padding: 14px;
  }

}

sp_widget.script:
(function() {

    data.assessments = [];


    // -----------------------------------------
    // GET ASSESSMENTS
    // -----------------------------------------

    var assessments = new GlideRecord(
        'x_snc_campus360_student_assessment'
    );

    assessments.orderByDesc('assessment_date');
    assessments.query();


    // -----------------------------------------
    // PREVENT DUPLICATE ASSESSMENTS
    // -----------------------------------------

    var seen = {};


    while (assessments.next()) {

        var assessmentId =
            assessments.getValue('assessment_id');

        /*
         * Student Assessment contains one record
         * for each student.
         *
         * Therefore the same assessment may appear
         * multiple times.
         *
         * Use Assessment ID to display it only once.
         */

        if (assessmentId && seen[assessmentId]) {
            continue;
        }

        if (assessmentId) {
            seen[assessmentId] = true;
        }


        var assessment = {};


        // -----------------------------------------
        // SYS ID
        // -----------------------------------------

        assessment.sys_id =
            assessments.getUniqueValue();


        // -----------------------------------------
        // ASSESSMENT ID
        // -----------------------------------------

        assessment.assessment_id =
            assessments.getValue('assessment_id');


        // -----------------------------------------
        // ASSESSMENT NAME
        // -----------------------------------------

        assessment.assessment_name =
            assessments.getValue('assessment_name');


        // -----------------------------------------
        // ASSESSMENT TYPE
        // -----------------------------------------

        assessment.assessment_type =
            assessments.getDisplayValue('assessment_type');


        // -----------------------------------------
        // ASSESSMENT DATE
        // -----------------------------------------

        assessment.assessment_date =
            assessments.getDisplayValue('assessment_date');


        // -----------------------------------------
        // MAXIMUM SCORE
        // -----------------------------------------

        assessment.maximum_score =
            assessments.getValue('maximum_score');


        // -----------------------------------------
        // STATUS
        // -----------------------------------------

        if (assessments.status) {

            assessment.status =
                assessments.getDisplayValue('status');

        } else {

            // Fallback for records created before
            // Status field was added.

            assessment.status = 'Published';

        }


        // -----------------------------------------
        // OPPORTUNITY
        // -----------------------------------------

        if (assessments.opportunity) {

            assessment.opportunity =
                assessments.opportunity.getDisplayValue();

        } else {

            assessment.opportunity =
                'Placement Opportunity';

        }


        // -----------------------------------------
        // STUDENT COUNT
        // -----------------------------------------

        var studentCount = new GlideAggregate(
            'x_snc_campus360_student_assessment'
        );

        studentCount.addQuery(
            'assessment_id',
            assessmentId
        );

        studentCount.addAggregate('COUNT');
        studentCount.query();


        assessment.student_count = 0;

        if (studentCount.next()) {

            assessment.student_count =
                parseInt(
                    studentCount.getAggregate('COUNT'),
                    10
                );

        }


        data.assessments.push(assessment);

    }


})();

data.aiWidget = $sp.getWidget('campus360_ai_assistant');
